import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return 0.002 * ((x1**2) + (1.5 * x2**2) + 0.7 * x1 * x2 + 0.1 * (x1**3 + x2**3) + 0.2 * x1 + 0.1 * x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]

    return 0.5 * (x1**2 + x2**2) + 0.1 * x1 * x2 + 0.05 * x1**3 + 0.01 * np.sin(2 * x1) * np.cos(3 * x2)

