import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return 0.002 * ((x1**2) + (2 * x2**2) - 0.6 * x1 * x2 + 0.2 * np.sinh(x1) + 0.1* x1 * x2 * (x1 + x2))

