import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return 0.002 * ( (x1**2 + 1.2 * x2**2 + 0.5 * x1*x2) + 0.3*np.sin(2*x1 - x2) + 0.1 * np.exp(x1 - 0.5*x2) + 0.05*x1)

